    <aside class="hidden md:flex flex-col w-64 bg-sidebar border-r border-border-muted h-full shrink-0"><div class="h-14 flex items-center px-5 border-b border-border-muted font-semibold text-lg tracking-tight bg-surface-subtle">Helios</div><nav class="flex-1 overflow-y-auto p-inline-md space-y-stack-xs"><router-link v-for="item in navItems" :key="item.name" :to="item.path" class="flex items-center px-inline-md py-stack-sm rounded-control text-body" :class="$route.path===item.path?'bg-state-selected text-ink font-semibold':'text-ink-secondary hover:bg-surface-subtle'"><span class="mr-3">{{item.icon}}</span>{{item.name}}</router-link></nav><div class="p-inline-md border-t border-border-muted"><button @click="handleSignOut" class="flex items-center w-full px-inline-md py-stack-sm rounded-control text-body text-ink-secondary hover:bg-surface-subtle">🚪 <span class="ml-3">Sign out</span></button></div></aside>
