<script setup>import{ref,computed}from'vue';import{useRoute}from'vue-router';import{supabase}from'../lib/supabase.js';const route=useRoute(),isMobileMenuOpen=ref(false);const handleSignOut=async()=>{if(supabase)await supabase.auth.signOut()};const navItems=[{name:'Overview',path:'/',icon:'📊'},{name:'Calendar',path:'/calendar',icon:'🗓️'},{name:'Schedule',path:'/schedule',icon:'➕'},{name:'Clients',path:'/clients',icon:'👥'},{name:'Transcripts',path:'/transcripts',icon:'📝'},{name:'Documents',path:'/documents',icon:'📄'},{name:'Professional Development',path:'/supervision',icon:'🌱'},{name:'Settings',path:'/settings',icon:'⚙️'}];const currentPageName=computed(()=>navItems.find(item=>item.path===route.path)?.name||'Workspace');</script>
